function report = run_cad_pressure_history(bundlePath)
%RUN_CAD_PRESSURE_HISTORY Nonlinear UVLM control, synchronized pressure/TE/work.
% Deliberately small 8x6 verification lattice, not a converged skin-Cp claim.
root=fileparts(fileparts(mfilename('fullpath')));s=load(bundlePath,'bundle');b=s.bundle;m=b.model;flow=b.flow;assert(b.surface.nx==8 && b.surface.ny==6,'cad:Pressure','This verification control requires its declared 8x6 lattice.');
out=fullfile(root,'results/cad_original/pressure_history');if ~isfolder(out),mkdir(out);end;b.config.discretization.dampingRatio=m.zeta;b.config.provenance.runtimeOverrides='actual reduced-model damping; pressure observation does not alter the coupled force';cad.provenance(root,b.config,out);
options=struct('wakeLength',1000*flow.referenceChord);uv=m;uv.aero=@(X,V,f)fsi.uvlm_static(X,V,f,options);eq=fsi.static(uv,flow);
m.X0=reshape(reshape(m.X0,[],3)+reshape(m.PhiSurface*eq.q,3,[])',size(m.X0));time=0:.0005:.1;fluid=uvlm.linear_model(m.X0,m.PhiSurface,flow,.0005,numel(time),options);g=fluid.state0.geometry;
N=zeros(numel(m.X0),size(m.K,1));for j=1:size(m.K,1),nodal=g.Hcent'*(flow.rho*g.panels.area.*g.panels.normal.*fluid.E(:,j));N(:,j)=reshape(nodal',[],1);end
m.nodalAccelerationLoad=N;m.pressureAccelerationLoad=flow.rho*fluid.E;m.initializeFluid=@initialize;m.advanceFluid=@advance;baseline=fluid.base.nodalForces;
q0=zeros(size(m.K,1),1);q0(1)=1e-5/max(abs(m.observation(:,1)));r=fsi.dynamic(m,flow,time,q0,zeros(size(q0)),struct('relaxation',.8,'relativeTolerance',1e-8,'forceScale',norm(m.K*q0),'storePressureHistory',true));Y=m.observation*r.Q;
points=g.Hcent*reshape(m.X0,[],3);[~,index]=min((points(:,1)/flow.referenceChord-.8).^2+(points(:,2)/b.config.geometry.span_m).^2);perturbation=r.pressureHistory_Pa-fluid.base.pressureJump;
writematrix([time',r.pressureHistory_Pa'],fullfile(out,'equivalent_pressure_history.csv'));writematrix([time',Y',r.energy',r.aerodynamicWork',r.dissipation'],fullfile(out,'motion_energy.csv'));writematrix([points,g.panels.area,fluid.base.pressureJump],fullfile(out,'material_panels.csv'));
report=struct('panels',[g.nx,g.ny],'timeWindow_s',[time(1),time(end)],'timeStep_s',time(2)-time(1),'maximumPressurePerturbation_Pa',max(abs(perturbation),[],'all'),'energyDefect',r.relativeEnergyBalance,'interfaceWorkDefect_J',r.maximumInterfaceWorkDefect,'observedPanel',index,'observedCoordinates_m',points(index,:),'scope','nonlinear strongly coupled CAD control; equivalent normal thin-surface pressure, not two-skin Cp; coarse 8x6 verification only; no imposed oscillating pressure');
report.dampingRatioAssumed=m.zeta;report.sourceBundle=bundlePath;report.sourceBundleSha256=cad.sha256(bundlePath);geometryReference=struct('nodesAtEquilibrium',reshape(m.X0,[],3),'PhiSurface',m.PhiSurface,'panelH',g.Hcent,'observation',m.observation);
cad.write_json(fullfile(out,'scope.json'),report);save(fullfile(out,'response.mat'),'r','Y','points','geometryReference','report','-v7.3');
fig=figure('Visible','off','Color','w','Position',[100,100,1100,850]);if isprop(fig,'Theme'),fig.Theme='light';end;tiledlayout(3,1);nexttile;plot(time,perturbation(index,:));grid on;xlabel('t [s]');ylabel('delta presión [Pa]');title(sprintf('Control CAD 8x6: panel material x/c=%.3f, eta=%.3f',points(index,1)/flow.referenceChord,points(index,2)/b.config.geometry.span_m+.5));nexttile;plot(time,1e3*Y);grid on;xlabel('t [s]');ylabel('perturbación TE [mm]');nexttile;plot(time,r.energy-r.energy(1),time,r.aerodynamicWork-r.dissipation);grid on;xlabel('t [s]');ylabel('energía [J]');legend('Cambio estructural','Trabajo aerodinámico - disipación');exportgraphics(fig,fullfile(out,'synchronized_pressure_motion.png'),'Resolution',150);close(fig);disp(report);
 function [state,aero]=initialize(X,V,f),[state,aero]=uvlm.initialize(X,V,f,options);aero.nodalForces=aero.nodalForces-baseline;end
 function [state,aero]=advance(old,X,V,f,dt),[state,aero]=uvlm.step(old,X,V,f,dt);aero.nodalForces=aero.nodalForces-baseline;end
end
